code_examples.flask:
from urllib.parse import urlparse
ALLOWED_HOSTS = {'target.example.com'}
@app.route('/login')
def login():
    next_url = request.args.get('next', '/')
    p = urlparse(next_url)
    if p.scheme or p.netloc:  # absolute URL — reject
        return 'invalid redirect', 400
    if not next_url.startswith('/'):
        next_url = '/' + next_url
    return redirect(next_url)

code_examples.django:
from django.utils.http import url_has_allowed_host_and_scheme
def safe_redirect(request):
    nxt = request.GET.get('next', '/')
    if url_has_allowed_host_and_scheme(nxt, allowed_hosts={request.get_host()}, require_https=request.is_secure()):
        return redirect(nxt)
    return redirect('/')

code_examples.express:
function safeRedirect(req, res, next) {
  const nxt = req.query.next || '/';
  if (/^\/[\w/-]*$/.test(nxt)) {
    return res.redirect(nxt);
  }
  return res.redirect('/');
}

